$('draft_inspectors').oninput=()=>{$('draft_inspectors').dataset.reset='false';};
$('cancelReportDetails').onclick=()=>$('reportDetailsDialog').close();
$('reportDetailsForm').onsubmit=e=>{e.preventDefault();if(!$('draft_title').value.trim()){$('draft_title').setCustomValidity('Enter a report title.');$('draft_title').reportValidity();return;}if($('draft_inspectors').dataset.reset==='true')$('inspectorsEdited').checked=false;else if($('draft_inspectors').value!==$('draft_inspectors').dataset.initial)$('inspectorsEdited').checked=true;for(const key of detailKeys)$(key).value=$('draft_'+key).value.trim();$('reportDetailsDialog').close();render();document.dispatchEvent(new Event('report-changed'));$('saveReport').click();};
$('draft_title').oninput=()=>$('draft_title').setCustomValidity('');
let optionRevision=0;
async function refreshReportFieldPreview(){const revision=++optionRevision;document.dispatchEvent(new Event('report-changed'));$('optionStatus').textContent='Updating preview…';try{const target=document.createElement('div');await previewReport(reportData(),target);if(revision===optionRevision){$('report').replaceChildren(...target.childNodes);$('optionStatus').textContent='Preview updated. Options are retained with this report.';}}catch(e){if(revision===optionRevision)$('optionStatus').textContent='Preview could not update: '+e.message;}}
for(const key of ['coverPage','includeContents','pptSinglePhoto','pptSourceAppendix','findingsLayout'])$(key).onchange=refreshReportFieldPreview;
function readReportFields(){return [...document.querySelectorAll('[data-report-field]:checked')].map(input=>input.dataset.reportField);}
function syncReportFields(){const selection=readReportFields(),preset=reportPreset(selection);$('includeRecommendedAction').checked=selection.includes('recommendedAction');$('departmentResponse').checked=selection.includes('departmentResponse');$('reportFieldSummary').textContent=['Finding number','Observation',...REPORT_FIELDS.filter(([key])=>selection.includes(key)).map(([,label])=>label)].join(' · ');for(const button of document.querySelectorAll('[data-field-preset]'))button.setAttribute('aria-pressed',String(button.dataset.fieldPreset===preset));$('customPresetLabel').hidden=preset!=='custom';}
function setReportFields(selection){for(const input of document.querySelectorAll('[data-report-field]'))input.checked=selection.includes(input.dataset.reportField);syncReportFields();}
for(const input of document.querySelectorAll('[data-report-field]'))input.onchange=()=>{if(state.exporting)return;syncReportFields();refreshReportFieldPreview();};
for(const button of document.querySelectorAll('[data-field-preset]'))button.onclick=()=>{if(state.exporting)return;lastFieldPreset=button.dataset.fieldPreset;setReportFields(REPORT_PRESETS[lastFieldPreset]);refreshReportFieldPreview();};
$('resetReportFields').onclick=()=>{if(state.exporting)return;setReportFields(REPORT_PRESETS[lastFieldPreset]);refreshReportFieldPreview();};
$('doneReportFields').onclick=()=>{$('reportFieldOptions').open=false;};
setReportFields(REPORT_PRESETS.inspection);

$('editor').addEventListener('input',()=>{updateReportDetails();if(state.rows.length)showCheck($('reportCheck'),reportData());});$('preparedDate').addEventListener('change',updateReportDetails);

$('groups').onchange=e=>{const field=e.target.dataset.inspectionField;if(!field)return;const id=e.target.closest('[data-group]').dataset.group;const original=state.rows.find(r=>r.inspection.id===id).inspection;state.groupEdits[id]={...(state.groupEdits[id]||original),[field]:e.target.value};render();};
$('groupFindings').onclick=()=>{if(state.busy)return;$('groupFindingsDialog').showModal();};
$('cancelGroupFindings').onclick=()=>$('groupFindingsDialog').close();
$('confirmGroupFindings').onclick=()=>{if(state.busy)return;state.rows=groupFindingsByInspection(state.rows);$('groupFindingsDialog').close();render();textStatus('Findings grouped by inspection. Finding numbers and exports follow this order.');};
$('reset').onclick=()=>{if(!state.busy)$('clearDialog').showModal();};
$('cancelClear').onclick=()=>$('clearDialog').close();
$('confirmClear').onclick=()=>{if(state.busy)return;$('clearDialog').close();for(const r of state.rows)release(r);for(const c of state.conflicts)release(c.incoming);state.rows=[];state.imports=[];state.conflicts=[];state.bytes=0;state.expanded=0;state.groupEdits={};state.openFindings.clear();$('title').value='Safety inspection report';for(const id of ['department','reference','purpose','summary','search'])$(id).value='';$('filter').value='';render();textStatus('Session cleared.');};

render();
const reportFields=['inspectors','inspectorsEdited','title','department','reference','purpose','summary','preparedDate','coverPage','includeContents','pptSinglePhoto','pptSourceAppendix','findingsLayout','departmentResponse','includeRecommendedAction'];
const sgToday=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Singapore',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function emptyProject(){return{rows:[],imports:[],conflicts:[],bytes:0,expanded:0,groupEdits:{},fields:{inspectors:'',inspectorsEdited:false,title:'Safety inspection report',department:'',reference:'',purpose:'',summary:'',preparedDate:sgToday(),coverPage:false,includeContents:false,pptSinglePhoto:false,pptSourceAppendix:false,findingsLayout:'individual',departmentResponse:false,includeRecommendedAction:true,reportFieldSelection:[...REPORT_PRESETS.inspection],reportFieldPreset:'inspection'}};}
function captureProject(){return stripURLs({rows:state.rows.map(r=>findingDraft&&r.key===findingDraft.original.key?findingDraft.original:r),imports:state.imports,conflicts:state.conflicts,bytes:state.bytes,expanded:findingDraft?findingDraft.expanded:state.expanded,groupEdits:state.groupEdits,fields:{...Object.fromEntries(reportFields.map(k=>[k,$(k).type==='checkbox'?$(k).checked:$(k).value])),reportFieldSelection:readReportFields(),reportFieldPreset:lastFieldPreset}});}
function loadProject(snapshot){selectedFindings.clear();selectingFindings=false;
 projectGeneration++;ai?.reset();
 const next=structuredClone(snapshot),created=[];
 try{for(const row of [...next.rows,...next.conflicts.map(c=>c.incoming)])for(const photo of row.photos)for(const v of Object.values(photo.variants))if(v){if(!(v.blob instanceof Blob))throw Error('A saved photograph is unavailable.');v.url=URL.createObjectURL(v.blob);created.push(v.url);}}
 catch(e){created.forEach(URL.revokeObjectURL);throw e;}
 for(const row of state.rows)release(row);for(const c of state.conflicts)release(c.incoming);
 Object.assign(state,{rows:next.rows,imports:next.imports,conflicts:next.conflicts,bytes:next.bytes,expanded:next.expanded,groupEdits:next.groupEdits,openFindings:new Set()});
 for(const k of reportFields){if($(k).type==='checkbox')$(k).checked=k==='includeRecommendedAction'?next.fields[k]!==false:!!next.fields[k];else $(k).value=next.fields[k]??(k==='findingsLayout'?'individual':'');}lastFieldPreset=next.fields.reportFieldPreset||((reportPreset(migrateReportFields(next))==='followup')?'followup':'inspection');setReportFields(migrateReportFields(next));$('reportFieldOptions').open=false;$('search').value='';$('filter').value='';$('inclusionFilter').value='included';$('status').textContent='';render();
}
const dashboardReady=startDashboard({capture:captureProject,load:loadProject,empty:emptyProject,busy:()=>state.busy||state.exporting,download:save});
startPWA({prepareUpdate:async()=>{if(state.busy||state.exporting||findingDraft||document.querySelector('dialog[open]'))throw Error('Finish or cancel open edits and file processing before updating.');const dashboard=await dashboardReady;await dashboard.save();}});

const aiSnapshot=()=>JSON.stringify(reportData(),(k,v)=>['photos','original','sources','signature'].includes(k)?undefined:v);
if(AI_ENABLED){document.querySelector('.ai-toolbar').hidden=false;ai=startAI({busy:()=>state.busy,notify:textStatus,
 select(action,index){if(state.conflicts.length){textStatus('Resolve conflicting findings before requesting AI assistance.','warning');return null;}const data=reportData(),row=index==null?null:state.rows[index],rows=action==='summary'?data.rows:row?[{...row,inspection:state.groupEdits[row.inspection.id]||row.inspection}]:[];if(!rows.length||!rows.some(r=>r.edit.description?.trim()))return null;return {action,key:row?.key,generation:projectGeneration,snapshot:aiSnapshot(),current:action==='summary'?$('summary').value:row.edit[action==='observation'?'description':'action']||'',payload:{action,title:data.title,findings:rows.map(r=>({reference:r.edit.reference||r.original.reference||'',inspectionDate:r.inspection.date||'',location:loc(r.edit),observation:r.edit.description||'',correctiveAction:r.edit.action||''}))}};},
 apply(selection,text){if(selection.generation!==projectGeneration||selection.snapshot!==aiSnapshot())return null;const field=selection.action==='summary'?'summary':selection.action==='observation'?'description':'action',row=state.rows.find(r=>r.key===selection.key);if(field!=='summary'&&!row)return null;const old=field==='summary'?$('summary').value:row.edit[field]||'';if(field==='summary'){$('summary').value=text;$('summary').closest('details').open=true;}else row.edit[field]=text;render();return{generation:projectGeneration,key:selection.key,field,old,text};},
 undo(change){if(change.generation!==projectGeneration)return false;const row=state.rows.find(r=>r.key===change.key);if(change.field==='summary'){if($('summary').value!==change.text)return false;$('summary').value=change.old;}else{if(!row||row.edit[change.field]!==change.text)return false;row.edit[change.field]=change.old;}render();return true;}
});
}

$('photoFiles').onchange=async e=>{
 const files=[...e.target.files],target=photoTarget;photoTarget=null;e.target.value='';if(!files.length||!target||state.busy)return;
 const row=state.rows.find(r=>r.key===target.key);if(!row||target.generation!==projectGeneration){textStatus('The report changed. Open the finding and select your photos again.','warning');return;}
 if(files.length>20){textStatus('Select up to 20 photos at a time.','warning');return;}
 state.busy=true;render();let added=0;const failures=[];
 try{for(const file of files){try{
  textStatus('Adding photo '+(files.indexOf(file)+1)+' of '+files.length+': '+file.name+'…');
  if(file.size>PHOTO_LIMIT)throw Error('Exceeds the 20 MB photo limit.');if(state.expanded+file.size>LIMITS.expanded)throw Error('This report has reached the 1 GB expanded file limit.');
  const bytes=new Uint8Array(await file.arrayBuffer()),mime=imageMime(bytes);if(!mime)throw Error('Choose a JPEG or PNG image.');const blob=new Blob([bytes],{type:mime});
  const bitmap=await createImageBitmap(blob);const pixels=bitmap.width*bitmap.height;bitmap.close();if(pixels>80000000)throw Error('Image exceeds 80 megapixels. Use a smaller copy.');
  const photo=addedPhoto(file,blob,row.photos,URL.createObjectURL(blob));row.photos.push(photo);state.expanded+=bytes.length;added++;
 }catch(error){failures.push(file.name+': '+error.message);}}}
 finally{state.busy=false;render();textStatus(added+' photo'+(added===1?'':'s')+' added to this finding.'+(failures.length?' '+failures.join(' '):''),failures.length?'warning':'info');}
};

document.addEventListener('click',e=>{if(!e.target.closest('#findingFilters'))$('findingFilters').open=false;});
document.addEventListener('keydown',e=>{if(e.key==='Escape')$('findingFilters').open=false;});

$("openUserHelp").onclick=()=>$("userHelpDialog").showModal();
$("closeUserHelp").onclick=()=>$("userHelpDialog").close();

const storageProtectionControl=startStorageProtection({storage:navigator.storage,button:$("requestStorageProtection"),status:$("storageProtectionStatus")});
document.addEventListener("visibilitychange",()=>{if(!document.hidden)storageProtectionControl.refresh();});
